def is_power_of_p(N, p):
    if N <= 0:
        return False
    if N == 1:
        # While technically p^0, the sums here should be larger than p since p >= 7 and a, b >= p-1 >= 6
        return False 

    while N > 1:
        if N % p != 0:
            return False
        N //= p
    return True

def check_triple(p, a, b):
    # Check the constraints specific to the task
    if not (a % p == p - 1 and b % p == p - 1):
        return False, None

    # Check the power conditions
    LHS1 = a**(p-1) + b
    LHS2 = b**(p-1) + a

    is_pow1 = is_power_of_p(LHS1, p)
    is_pow2 = is_power_of_p(LHS2, p)

    if is_pow1 and is_pow2:
        return True, (p, a, b)
    return False, None

# --- Case p = 7 ---
p7 = 7
p_minus_1 = p7 - 1
range_min = p_minus_1
range_max = 2 * p7 - 1

found_p7 = []
# Iterating over all possible a and b in the required range and checking modular constraint
for a in range(range_min, range_max + 1):
    if a % p7 != p_minus_1:
        continue
    for b in range(a, range_max + 1):
        if b % p7 != p_minus_1:
            continue

        success, triple = check_triple(p7, a, b)
        if success:
            found_p7.append(triple)

