def check_solution(p, a, b):
    if p <= 2 or a <= 0 or b <= 0 or a > b:
        return False

    # Check a^(p-1) + b = p^x
    term1 = a**(p-1) + b
    if term1 <= 0: return False
    x = 0
    if term1 > 0:
        temp = term1
        while temp > 1 and temp % p == 0:
            temp //= p
            x += 1
        if temp != 1:
            return False

    # Check b^(p-1) + a = p^y
    term2 = b**(p-1) + a
    if term2 <= 0: return False
    y = 0
    if term2 > 0:
        temp = term2
        while temp > 1 and temp % p == 0:
            temp //= p
            y += 1
        if temp != 1:
            return False

    return True

